PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE IF NOT EXISTS "django_migrations" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "app" varchar(255) NOT NULL, "name" varchar(255) NOT NULL, "applied" datetime NOT NULL);
CREATE TABLE IF NOT EXISTS "django_content_type" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "app_label" varchar(100) NOT NULL, "model" varchar(100) NOT NULL);
CREATE TABLE IF NOT EXISTS "auth_group_permissions" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "group_id" integer NOT NULL REFERENCES "auth_group" ("id") DEFERRABLE INITIALLY DEFERRED, "permission_id" integer NOT NULL REFERENCES "auth_permission" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "auth_permission" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "content_type_id" integer NOT NULL REFERENCES "django_content_type" ("id") DEFERRABLE INITIALLY DEFERRED, "codename" varchar(100) NOT NULL, "name" varchar(255) NOT NULL);
CREATE TABLE IF NOT EXISTS "auth_group" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(150) NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS "core_user" ("password" varchar(128) NOT NULL, "last_login" datetime NULL, "is_superuser" bool NOT NULL, "username" varchar(150) NOT NULL UNIQUE, "first_name" varchar(150) NOT NULL, "last_name" varchar(150) NOT NULL, "email" varchar(254) NOT NULL, "is_staff" bool NOT NULL, "is_active" bool NOT NULL, "date_joined" datetime NOT NULL, "id" char(32) NOT NULL PRIMARY KEY, "company_id" char(32) NULL REFERENCES "core_company" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "core_company" ("id" char(32) NOT NULL PRIMARY KEY, "name" varchar(255) NOT NULL, "address" text NOT NULL, "phone" varchar(64) NOT NULL, "created_at" datetime NOT NULL);
CREATE TABLE IF NOT EXISTS "core_equipment" ("id" char(32) NOT NULL PRIMARY KEY, "name" varchar(255) NOT NULL, "serial_number" varchar(255) NOT NULL, "purchase_date" date NULL, "last_service_date" date NULL, "created_at" datetime NOT NULL, "company_id" char(32) NOT NULL REFERENCES "core_company" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "core_material" ("id" char(32) NOT NULL PRIMARY KEY, "sku" varchar(128) NOT NULL, "name" varchar(255) NOT NULL, "description" text NOT NULL, "unit" varchar(32) NOT NULL, "created_at" datetime NOT NULL, "company_id" char(32) NOT NULL REFERENCES "core_company" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "core_project" ("id" char(32) NOT NULL PRIMARY KEY, "name" varchar(255) NOT NULL, "code" varchar(64) NOT NULL, "description" text NOT NULL, "start_date" date NULL, "end_date" date NULL, "status" varchar(32) NOT NULL, "created_at" datetime NOT NULL, "company_id" char(32) NOT NULL REFERENCES "core_company" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "core_purchaseorder" ("id" char(32) NOT NULL PRIMARY KEY, "supplier" varchar(255) NOT NULL, "order_date" date NOT NULL, "status" varchar(32) NOT NULL, "total" decimal NOT NULL, "created_at" datetime NOT NULL, "company_id" char(32) NOT NULL REFERENCES "core_company" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "core_role" ("id" char(32) NOT NULL PRIMARY KEY, "name" varchar(64) NOT NULL UNIQUE, "description" text NOT NULL);
CREATE TABLE IF NOT EXISTS "core_worker" ("id" char(32) NOT NULL PRIMARY KEY, "first_name" varchar(128) NOT NULL, "last_name" varchar(128) NOT NULL, "phone" varchar(64) NOT NULL, "role" varchar(128) NOT NULL, "trade" varchar(128) NOT NULL, "created_at" datetime NOT NULL, "company_id" char(32) NOT NULL REFERENCES "core_company" ("id") DEFERRABLE INITIALLY DEFERRED, "user_id" char(32) NULL UNIQUE REFERENCES "core_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "core_timesheet" ("id" char(32) NOT NULL PRIMARY KEY, "date" date NOT NULL, "hours" decimal NOT NULL, "notes" text NOT NULL, "created_at" datetime NOT NULL, "task_id" char(32) NULL REFERENCES "core_task" ("id") DEFERRABLE INITIALLY DEFERRED, "worker_id" char(32) NOT NULL REFERENCES "core_worker" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "core_task" ("id" char(32) NOT NULL PRIMARY KEY, "title" varchar(255) NOT NULL, "description" text NOT NULL, "start_date" date NULL, "due_date" date NULL, "priority" varchar(16) NOT NULL, "status" varchar(32) NOT NULL, "estimate_hours" decimal NULL, "created_at" datetime NOT NULL, "assigned_to_id" char(32) NULL REFERENCES "core_worker" ("id") DEFERRABLE INITIALLY DEFERRED, "project_id" char(32) NOT NULL REFERENCES "core_project" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "core_purchaseorderline" ("id" char(32) NOT NULL PRIMARY KEY, "description" varchar(512) NOT NULL, "quantity" decimal NOT NULL, "unit_price" decimal NOT NULL, "created_at" datetime NOT NULL, "material_id" char(32) NULL REFERENCES "core_material" ("id") DEFERRABLE INITIALLY DEFERRED, "purchase_order_id" char(32) NOT NULL REFERENCES "core_purchaseorder" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "core_maintenancerecord" ("id" char(32) NOT NULL PRIMARY KEY, "performed_by" varchar(255) NOT NULL, "notes" text NOT NULL, "date" date NOT NULL, "created_at" datetime NOT NULL, "equipment_id" char(32) NOT NULL REFERENCES "core_equipment" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "core_invoice" ("id" char(32) NOT NULL PRIMARY KEY, "number" varchar(128) NOT NULL, "date" date NOT NULL, "due_date" date NULL, "amount" decimal NOT NULL, "status" varchar(32) NOT NULL, "created_at" datetime NOT NULL, "company_id" char(32) NOT NULL REFERENCES "core_company" ("id") DEFERRABLE INITIALLY DEFERRED, "project_id" char(32) NULL REFERENCES "core_project" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "core_inspection" ("id" char(32) NOT NULL PRIMARY KEY, "notes" text NOT NULL, "photo" varchar(100) NULL, "date" datetime NOT NULL, "created_at" datetime NOT NULL, "inspector_id" char(32) NULL REFERENCES "core_user" ("id") DEFERRABLE INITIALLY DEFERRED, "project_id" char(32) NOT NULL REFERENCES "core_project" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "core_document" ("id" char(32) NOT NULL PRIMARY KEY, "file" varchar(100) NOT NULL, "filename" varchar(512) NOT NULL, "content_type" varchar(128) NOT NULL, "size" bigint NULL, "created_at" datetime NOT NULL, "company_id" char(32) NOT NULL REFERENCES "core_company" ("id") DEFERRABLE INITIALLY DEFERRED, "uploaded_by_id" char(32) NULL REFERENCES "core_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "core_activitylog" ("id" char(32) NOT NULL PRIMARY KEY, "action" varchar(255) NOT NULL, "detail" text NOT NULL, "created_at" datetime NOT NULL, "company_id" char(32) NOT NULL REFERENCES "core_company" ("id") DEFERRABLE INITIALLY DEFERRED, "user_id" char(32) NULL REFERENCES "core_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "core_user_groups" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "user_id" char(32) NOT NULL REFERENCES "core_user" ("id") DEFERRABLE INITIALLY DEFERRED, "group_id" integer NOT NULL REFERENCES "auth_group" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "core_user_roles" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "user_id" char(32) NOT NULL REFERENCES "core_user" ("id") DEFERRABLE INITIALLY DEFERRED, "role_id" char(32) NOT NULL REFERENCES "core_role" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "core_user_user_permissions" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "user_id" char(32) NOT NULL REFERENCES "core_user" ("id") DEFERRABLE INITIALLY DEFERRED, "permission_id" integer NOT NULL REFERENCES "auth_permission" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "django_admin_log" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "object_id" text NULL, "object_repr" varchar(200) NOT NULL, "action_flag" smallint unsigned NOT NULL CHECK ("action_flag" >= 0), "change_message" text NOT NULL, "content_type_id" integer NULL REFERENCES "django_content_type" ("id") DEFERRABLE INITIALLY DEFERRED, "user_id" char(32) NOT NULL REFERENCES "core_user" ("id") DEFERRABLE INITIALLY DEFERRED, "action_time" datetime NOT NULL);
CREATE TABLE IF NOT EXISTS "django_session" ("session_key" varchar(40) NOT NULL PRIMARY KEY, "session_data" text NOT NULL, "expire_date" datetime NOT NULL);
DELETE FROM sqlite_sequence;
